pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, uint256 v, address to) public {
        vm.assume(to != address(0));
        vm.assume(from != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;

        ExactAmountReceiver helper = new ExactAmountReceiver(v);

        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ExactAmountReceiver {
    uint256 public expected;
    constructor(uint256 _expected) { expected = _expected; }

    function transferFrom(address, address, uint256 amount) external returns (bool) {
        require(amount == expected, "bad amount");
        return true;
    }
}
